      "title": "Pattern Printer",
      "question": "Create a program that prints various patterns (pyramid, diamond, hollow square) based on user choice. Use nested do-while loops.",
      "solution": "import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int choice;\n        \n        do {\n            System.out.println(\"\\n=== PATTERN MENU ===\");\n            System.out.println(\"1. Pyramid\");\n            System.out.println(\"2. Diamond\");\n            System.out.println(\"3. Hollow Square\");\n            System.out.println(\"4. Exit\");\n            System.out.print(\"Choice: \");\n            choice = sc.nextInt();\n            \n            if (choice >= 1 && choice <= 3) {\n                System.out.print(\"Enter size: \");\n                int n = sc.nextInt();\n                \n                switch (choice) {\n                    case 1:  // Pyramid\n                        int i = 1;\n                        do {\n                            int j = 1;\n                            do {\n                                System.out.print(\"  \");\n                                j++;\n                            } while (j <= n - i);\n                            int k = 1;\n                            do {\n                                System.out.print(\"* \");\n                                k++;\n                            } while (k <= 2 * i - 1);\n                            System.out.println();\n                            i++;\n                        } while (i <= n);\n                        break;\n                    case 2:  // Diamond\n                        i = 1;\n                        do {\n                            int j = 1;\n                            do {\n                                System.out.print(\"  \");\n                                j++;\n                            } while (j <= n - i);\n                            int k = 1;\n                            do {\n                                System.out.print(\"* \");\n                                k++;\n                            } while (k <= 2 * i - 1);\n                            System.out.println();\n                            i++;\n                        } while (i <= n);\n                        i = n - 1;\n                        do {\n                            int j = 1;\n                            do {\n                                System.out.print(\"  \");\n                                j++;\n                            } while (j <= n - i);\n                            int k = 1;\n                            do {\n                                System.out.print(\"* \");\n                                k++;\n                            } while (k <= 2 * i - 1);\n                            System.out.println();\n                            i--;\n                        } while (i >= 1);\n                        break;\n                    case 3:  // Hollow Square\n                        i = 1;\n                        do {\n                            int j = 1;\n                            do {\n                                if (i == 1 || i == n || j == 1 || j == n) {\n                                    System.out.print(\"* \");\n                                } else {\n                                    System.out.print(\"  \");\n                                }\n                                j++;\n                            } while (j <= n);\n                            System.out.println();\n                            i++;\n                        } while (i <= n);\n                        break;\n                }\n            } else if (choice != 4) {\n                System.out.println(\"Invalid choice\");\n            }\n        } while (choice != 4);\n        \n        System.out.println(\"Thank you!\");\n        sc.close();\n    }\n}",
